 ids=np.array(m['tetrahedra']);f=boundary(t[ids]);c=v[t[ids]].mean(1);direction=np.array(m['fibreDirections']).reshape(-1,3);records[f'family_{i}_boundary_faces']=f;records[f'family_{i}_fibre_centers']=c;records[f'family_{i}_fibre_directions']=direction;records[f'family_{i}_tetrahedron_ids']=ids;meta.append({'index':i,'id':m['id'],'scope':m['scope'],'tetrahedra':len(ids),'surface_faces':len(f),'active_control':i<2,'volume_fraction':m.get('volumeFraction','per-cell' if 'volumeFractions' in m else 1)})
